-- EKPI platform: PostgreSQL 18.6 baseline schema.
--
-- Every identifier is generated by the application, every timestamp is stored
-- as TIMESTAMPTZ and every mutable column carries a constraint. The audit
-- chain is append-only: rows are never updated or deleted, and the trigger
-- below rejects any attempt to do so.

CREATE TABLE users (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    username     TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    role         TEXT NOT NULL CHECK (role IN ('viewer', 'editor', 'approver', 'admin')),
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    disabled     BOOLEAN NOT NULL DEFAULT FALSE,
    CONSTRAINT users_username_not_blank CHECK (length(btrim(username)) > 0),
    CONSTRAINT users_username_length CHECK (char_length(username) <= 64)
);

CREATE TABLE sessions (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    token_hash   TEXT NOT NULL UNIQUE,
    username     TEXT NOT NULL REFERENCES users (username) ON DELETE CASCADE,
    role         TEXT NOT NULL CHECK (role IN ('viewer', 'editor', 'approver', 'admin')),
    csrf_token   TEXT NOT NULL,
    created_at   TIMESTAMPTZ NOT NULL,
    expires_at   TIMESTAMPTZ NOT NULL,
    idle_deadline TIMESTAMPTZ NOT NULL,
    CONSTRAINT sessions_deadline_order CHECK (idle_deadline <= expires_at)
);

CREATE INDEX sessions_username_idx ON sessions (username);
CREATE INDEX sessions_expires_at_idx ON sessions (expires_at);

CREATE TABLE login_failures (
    username         TEXT PRIMARY KEY REFERENCES users (username) ON DELETE CASCADE,
    failures         INTEGER NOT NULL DEFAULT 0,
    first_failure_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT login_failures_non_negative CHECK (failures >= 0)
);

CREATE TABLE governance_projects (
    id         TEXT PRIMARY KEY,
    name       TEXT NOT NULL,
    department TEXT NOT NULL,
    owner      TEXT NOT NULL,
    risk_tier  TEXT NOT NULL CHECK (risk_tier IN ('low', 'medium', 'high', 'critical')),
    created_at BIGINT NOT NULL,
    CONSTRAINT governance_projects_id_shape CHECK (id ~ '^[A-Za-z0-9_.-]{1,80}$')
);

CREATE INDEX governance_projects_risk_tier_idx ON governance_projects (risk_tier);

CREATE TABLE governance_evidence (
    id             TEXT PRIMARY KEY,
    project_id     TEXT NOT NULL REFERENCES governance_projects (id) ON DELETE CASCADE,
    title          TEXT NOT NULL,
    source_system  TEXT NOT NULL,
    source_url     TEXT NOT NULL,
    source_version TEXT NOT NULL,
    evidence_type  TEXT NOT NULL,
    owner          TEXT NOT NULL,
    created_at     BIGINT NOT NULL,
    CONSTRAINT governance_evidence_id_shape CHECK (id ~ '^[A-Za-z0-9_.-]{1,80}$')
);

CREATE INDEX governance_evidence_project_idx ON governance_evidence (project_id);

CREATE TABLE governance_evidence_reviews (
    evidence_id TEXT PRIMARY KEY REFERENCES governance_evidence (id) ON DELETE CASCADE,
    result      TEXT NOT NULL CHECK (result IN ('accepted', 'changes_requested')),
    reviewer    TEXT NOT NULL,
    note        TEXT NOT NULL DEFAULT '',
    reviewed_at BIGINT NOT NULL
);

CREATE TABLE governance_workflows (
    id           TEXT NOT NULL,
    version      INTEGER NOT NULL CHECK (version >= 1),
    title        TEXT NOT NULL,
    department   TEXT NOT NULL,
    owner        TEXT NOT NULL,
    description  TEXT NOT NULL DEFAULT '',
    stages       JSONB NOT NULL,
    status       TEXT NOT NULL CHECK (status IN ('draft', 'published')),
    created_at   BIGINT NOT NULL,
    published_at BIGINT,
    published_by TEXT,
    PRIMARY KEY (id, version),
    CONSTRAINT governance_workflows_id_shape CHECK (id ~ '^[A-Za-z0-9_.-]{1,80}$'),
    CONSTRAINT governance_workflows_publish_state CHECK (
        (status = 'draft' AND published_at IS NULL AND published_by IS NULL)
        OR (status = 'published' AND published_at IS NOT NULL AND published_by IS NOT NULL)
    )
);

CREATE TABLE governance_quality_cases (
    id           TEXT PRIMARY KEY,
    project_id   TEXT NOT NULL REFERENCES governance_projects (id) ON DELETE CASCADE,
    kind         TEXT NOT NULL CHECK (kind IN ('risk', 'change', 'finding', 'capa')),
    title        TEXT NOT NULL,
    description  TEXT NOT NULL DEFAULT '',
    owner        TEXT NOT NULL,
    due_date     DATE NOT NULL,
    status       TEXT NOT NULL CHECK (status IN ('open', 'in_progress', 'verification', 'closed')),
    created_at   BIGINT NOT NULL,
    updated_at   BIGINT NOT NULL,
    closure_note TEXT,
    CONSTRAINT governance_quality_cases_id_shape CHECK (id ~ '^[A-Za-z0-9_.-]{1,80}$')
);

CREATE INDEX governance_quality_cases_project_idx ON governance_quality_cases (project_id);
CREATE INDEX governance_quality_cases_status_idx ON governance_quality_cases (status);

CREATE TABLE governance_quality_case_updates (
    sequence   BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    case_id    TEXT NOT NULL REFERENCES governance_quality_cases (id) ON DELETE CASCADE,
    status     TEXT NOT NULL CHECK (status IN ('open', 'in_progress', 'verification', 'closed')),
    actor      TEXT NOT NULL,
    note       TEXT NOT NULL DEFAULT '',
    updated_at BIGINT NOT NULL
);

CREATE INDEX governance_quality_case_updates_case_idx ON governance_quality_case_updates (case_id);

CREATE TABLE governance_inspections (
    id         TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES governance_projects (id) ON DELETE CASCADE,
    reviewer   TEXT NOT NULL,
    created_at BIGINT NOT NULL,
    CONSTRAINT governance_inspections_id_shape CHECK (id ~ '^[A-Za-z0-9_.-]{1,80}$')
);

CREATE INDEX governance_inspections_project_idx ON governance_inspections (project_id);

CREATE TABLE governance_inspection_results (
    inspection_id     TEXT NOT NULL REFERENCES governance_inspections (id) ON DELETE CASCADE,
    item_id           TEXT NOT NULL,
    result            TEXT NOT NULL CHECK (result IN ('pass', 'fail', 'not_applicable')),
    note              TEXT NOT NULL DEFAULT '',
    evidence_reference TEXT NOT NULL DEFAULT '',
    issue_id          TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (inspection_id, item_id)
);

CREATE TABLE governance_gate_decisions (
    id                 TEXT PRIMARY KEY,
    project_id         TEXT NOT NULL REFERENCES governance_projects (id) ON DELETE CASCADE,
    gate_id            TEXT NOT NULL CHECK (gate_id IN ('G1', 'G2', 'G3', 'G4', 'G5')),
    decision           TEXT NOT NULL CHECK (decision IN ('go', 'hold', 'exception')),
    actor              TEXT NOT NULL,
    reason             TEXT NOT NULL DEFAULT '',
    evidence_reference TEXT NOT NULL DEFAULT '',
    risk_acceptor      TEXT NOT NULL DEFAULT '',
    remediation_due    DATE,
    non_waivable       BOOLEAN NOT NULL DEFAULT FALSE,
    created_at         BIGINT NOT NULL,
    CONSTRAINT governance_gate_decisions_id_shape CHECK (id ~ '^[A-Za-z0-9_.-]{1,80}$'),
    CONSTRAINT governance_gate_decisions_exception_fields CHECK (
        decision <> 'exception'
        OR (risk_acceptor <> '' AND remediation_due IS NOT NULL AND non_waivable = FALSE)
    )
);

CREATE INDEX governance_gate_decisions_project_idx ON governance_gate_decisions (project_id);

CREATE TABLE governance_audit_events (
    sequence        BIGINT PRIMARY KEY,
    occurred_at     BIGINT NOT NULL,
    actor           TEXT NOT NULL,
    event_type      TEXT NOT NULL,
    payload         JSONB NOT NULL,
    previous_sha256 TEXT NOT NULL,
    sha256          TEXT NOT NULL
);

CREATE OR REPLACE FUNCTION governance_audit_events_are_append_only()
RETURNS TRIGGER
LANGUAGE plpgsql
AS
$$
BEGIN
    RAISE EXCEPTION 'governance_audit_events is append-only; % is not allowed', TG_OP;
END
$$;

CREATE TRIGGER governance_audit_events_append_only
    BEFORE UPDATE OR DELETE ON governance_audit_events
    FOR EACH ROW
    EXECUTE FUNCTION governance_audit_events_are_append_only();
